package settings

import (
	"net/url"
	"time"
)

type ProbeSettings struct {
	HTTPListenAddress      string        `key:"probe_httpListenAddress" desc:"HTTP listen address for the Probe service" default:"localhost:8100" category:"Probe" usage:"Address the probe dashboard and API bind to" type:"string" longdesc:"### Purpose\nSpecifies the bind address for the Probe HTTP server.\n\n### Format\n- **host:port** - Binds to one interface\n- **:port** - Binds to all network interfaces\n\n### Recommendations\n- Keep the default **localhost:8100** unless a reverse proxy or tunnel exposes the probe\n- Every request needs the bearer token in **probe_authToken**"`
	AuthToken              string        `redact:"true" key:"probe_authToken" desc:"Bearer token required on every Probe request" default:"" category:"Probe" usage:"Required; the Probe service refuses to start when empty" type:"string" longdesc:"### Purpose\nStatic bearer token that clients present as 'Authorization: Bearer <token>' on every Probe request.\n\n### Behavior\nThe token is compared in constant time. An empty value makes the Probe service fail at startup.\n\n### Recommendations\n- Use a long random value\n- Never commit the token to a shared settings file"`
	SampleInterval         time.Duration `key:"probe_sampleInterval" desc:"Interval for sampling service metrics" default:"2s" category:"Probe" usage:"How often the probe scrapes fast sources" type:"duration" longdesc:"### Purpose\nInterval between samples of service Prometheus metrics.\n\n### Recommendations\n- Keep at 2s or higher to hold probe CPU use low"`
	SlowSampleInterval     time.Duration `key:"probe_slowSampleInterval" desc:"Interval for sampling Aerospike, Kafka and Postgres" default:"15s" category:"Probe" usage:"How often the probe queries data stores" type:"duration" longdesc:"### Purpose\nInterval between samples of Aerospike, Kafka and Postgres.\n\n### Recommendations\n- Keep between 10s and 15s to limit load on the data stores"`
	BaselineWarmup         time.Duration `key:"probe_baselineWarmup" desc:"Time to learn a baseline before alarms can fire" default:"30m" category:"Probe" usage:"Calibration period after start" type:"duration" longdesc:"### Purpose\nDuration the probe learns the normal level of each metric. The dashboard shows Calibrating and raises no fault until it ends."`
	SnoozeDefault          time.Duration `key:"probe_snoozeDefault" desc:"Default alarm snooze duration" default:"15m" category:"Probe" usage:"Length of a snooze when none is given" type:"duration" longdesc:"### Purpose\nDefault length of a snooze of one alarm when the operator gives no duration. The snooze applies to that alarm for all dashboards and survives a restart."`
	AlarmLogRetention      time.Duration `key:"probe_alarmLogRetention" desc:"How long the alarm log is kept" default:"168h" category:"Probe" usage:"Alarm log retention period" type:"duration" longdesc:"### Purpose\nAge after which the probe removes alarm log entries from its local store. The default is 7 days."`
	MetricsTargets         []string      `key:"probe_metricsTargets" desc:"Prometheus endpoints to scrape" default:"" category:"Probe" usage:"Pipe-separated host:port or URL list" type:"[]string" longdesc:"### Purpose\nList of Prometheus metrics endpoints of the Teranode services the probe scrapes.\n\n### Format\nPipe-separated entries. A **host:port** entry is scraped at **http://host:port/metrics**. A **host:port/path** entry is scraped at **http://host:port/path**. An entry with a scheme, such as **https://host:port/path**, is used as given. Empty entries are ignored.\n\n### Default\nEmpty means the probe reads the metrics registry of its own process."`
	StatePath              string        `key:"probe_statePath" desc:"Path of the probe local state store" default:"" category:"Probe" usage:"File path for baselines, snooze and alarm log" type:"string" longdesc:"### Purpose\nFile path of the local store that holds learned baselines, the snooze state and the alarm log."`
	AerospikeURL           *url.URL      `key:"probe_aerospikeURL" desc:"Aerospike URL the probe reads from" default:"" category:"Probe" usage:"Read-only Aerospike connection URL" type:"url" longdesc:"### Purpose\nAerospike connection URL used for read-only latency and namespace statistics. Credentials stay on the server."`
	PostgresURL            *url.URL      `key:"probe_postgresURL" desc:"Postgres URL the probe reads from" default:"" category:"Probe" usage:"Read-only Postgres connection URL" type:"url" longdesc:"### Purpose\nPostgres connection URL used for read-only statistics. Credentials stay on the server."`
	PostgresDiskCapacityGB float64       `key:"probe_postgresDiskCapacityGB" desc:"Postgres disk capacity in GB for the fill reading" default:"0" category:"Probe" usage:"Disk capacity of the Postgres volume in GB; 0 means unknown" type:"float64" longdesc:"### Purpose\nPostgres cannot report the capacity of its disk through SQL. The probe divides the database size by this value to show disk fill.\n\n### Values\n- **0** - Capacity unknown; the dashboard shows no data for Postgres disk fill\n- **> 0** - Disk capacity in gigabytes (1 GB = 1e9 bytes)"`
	Floors                 []string      `key:"probe_floors" desc:"Fixed per-metric floors" default:"" category:"Probe" usage:"Pipe-separated metric=value list" type:"[]string" longdesc:"### Purpose\nOperator-set fixed floors that override the learned baseline for a metric.\n\n### Format\nPipe-separated **metric=value** entries."`
}
